{
  "schemaVersion": "0.2",
  "slug": "password-input",
  "name": "PasswordInput",
  "family": "C",
  "status": "experimental",
  "purpose": "Password field with a visibility toggle and the same states as Input.",
  "scenarios": [
    "Login form credential entry",
    "Account password change",
    "API secret entry"
  ],
  "props": {
    "value": {
      "type": "string",
      "required": true,
      "description": "Current password value."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called with the new value on edit."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Field label."
    },
    "showLabel": {
      "type": "string",
      "required": true,
      "description": "Accessible label for revealing the password."
    },
    "hideLabel": {
      "type": "string",
      "required": true,
      "description": "Accessible label for concealing the password."
    },
    "disabled": {
      "type": "boolean",
      "required": false,
      "description": "Disable the field.",
      "default": false
    },
    "invalid": {
      "type": "boolean",
      "required": false,
      "description": "Mark the field invalid.",
      "default": false
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Masked input."
    },
    {
      "name": "revealed",
      "description": "Plain text input."
    },
    {
      "name": "invalid",
      "description": "Validation failure styling."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "card",
      "dialog",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not log or mirror the password value.",
    "Do not reveal the password by default."
  ],
  "a11y": {
    "role": "textbox",
    "keyboard": [
      "Tab moves between field and toggle"
    ],
    "focus": "Toggle is a button after the input in tab order.",
    "labeling": "Field label associates via the field primitive; toggle state uses aria-pressed.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Full width field at all breakpoints.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Full width.",
      "large": "Full width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "password-input",
    "states": [
      "default",
      "revealed",
      "invalid",
      "disabled"
    ],
    "intents": [
      "enter-text"
    ]
  }
}

import { FieldPrimitive } from '@chameleon-ui/primitives'
import { useState } from 'react'
import '../input/styles.css'
import './styles.css'

export interface PasswordInputProps {
  value: string
  onChange: (value: string) => void
  label: string
  showLabel: string
  hideLabel: string
  disabled?: boolean
  invalid?: boolean
  className?: string
}

export function PasswordInput({
  value,
  onChange,
  label,
  showLabel,
  hideLabel,
  disabled = false,
  invalid = false,
  className,
}: PasswordInputProps) {
  const [revealed, setRevealed] = useState(false)
  const classes = ['cu-password-input', className].filter(Boolean).join(' ')

  return (
    <FieldPrimitive.Root
      className="cu-field"
      disabled={disabled}
      invalid={invalid}
    >
      <FieldPrimitive.Label className="cu-field__label">{label}</FieldPrimitive.Label>
      <div
        className={classes}
        data-ai-role="password-input" data-ai-intent="enter-text"
        data-ai-state={invalid ? 'invalid' : disabled ? 'disabled' : revealed ? 'revealed' : 'default'}
      >
        <FieldPrimitive.Input
          className="cu-input cu-password-input__field"
          type={revealed ? 'text' : 'password'}
          autoComplete="current-password"
          value={value}
          onChange={(event) => onChange(event.currentTarget.value)}
        />
        <button
          type="button"
          className="cu-password-input__toggle"
          aria-label={revealed ? hideLabel : showLabel}
          aria-pressed={revealed}
          disabled={disabled}
          onClick={() => setRevealed((current) => !current)}
        >
          <span aria-hidden="true">{revealed ? '◡' : '◉'}</span>
        </button>
      </div>
    </FieldPrimitive.Root>
  )
}

.cu-password-input {
  position: relative;
  display: flex;
  align-items: stretch;
}

.cu-password-input .cu-password-input__field {
  flex: 1 1 auto;
  padding-inline-end: calc(var(--cu-touch-target-min) + var(--cu-space-2));
}

.cu-password-input__toggle {
  position: absolute;
  inset-inline-end: var(--cu-space-1);
  inset-block-start: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border: 0;
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-password-input__toggle:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.cu-password-input__toggle:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}
